class ElementManager2GError(Exception):
    """Basic exception for errors raised if some operations cannot be performed via EM2G.
    All other exceptions are handled internally in BtsManagerLib2G.dll or EquipmentControl.dll"""
    ROBOT_SUPPRESS_NAME = True


class ConnectionException(ElementManager2GError):
    """Raised if connection to 2G BTS fails due to various reasons"""


class CommissioningException(ElementManager2GError):
    """Raised if (un)commissioning fails"""


class UnexpectedObjectState(ElementManager2GError):
    """Raised if object state is different from expected state"""


class ResetLogicalObjectException(ElementManager2GError):
    """Raised if object state is different from expected state"""


class TraceCaptureError(Exception):
    """Basic exception for errors raised if some operations cannot be performed using TraceCapture"""


class TraceCaptureException(TraceCaptureError):
    """Raised if trace capture is tried on a Linux PC. Not supported yet!"""
